    /// <summary>
    /// The declaring key itself off the curve (Amendment 6 ruling 58, R6.62): 0 enrolled, 1 binding, 2 the post, 3 the declaration key's publication, 4 the declaration under it. The entry is of
    /// the closed form (<c>x</c> and <c>y</c> each 43 <c>A</c>) and no point on P-256, which is asked at the signature alone.
    /// </summary>
    private static Case DeclarationKeyOffCurve(string root, Key k1)
    {
        var (log, post, declarationKeyIndex, decl) = PostThenDeclaration(k1, "79");
        AddDeclaration(log, decl, root, "compromise-declaration-key-off-curve");
        return new Case("compromise-declaration-key-off-curve", "R6.62",
            "The key set lists the declaration key at 3 with x and y of 43 A each: an entry of the closed form that is no point on its curve. Whether a point lies on its curve is asked of the declaring key at the signature alone (R6.62(a), (g)), so the declaration is failed for a signature that does not verify; a reader that treats the entry as unreadable reports could not be checked.",
            log, post, [0, 1, 4], "failed", "declaration-signature-invalid")
        {
            DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, declarationKeyIndex, OffCurve: true)],
        };
    }

    /// <summary>Another declaration key off the curve (Amendment 6 ruling 58): the declaring key at 3 and a copy of it under the kid <c>extra-decl</c>, off the curve, at 9, after the declaration.</summary>
    private static Case OtherDeclarationKeyOffCurve(string root, Key k1)
    {
        var (log, post, declarationKeyIndex, decl) = PostThenDeclaration(k1, "80");
        AddDeclaration(log, decl, root, "compromise-other-declaration-key-off-curve");
        return new Case("compromise-other-declaration-key-off-curve", "R6.62",
            "The key set lists the declaration key at 3 and a copy of it under the kid extra-decl at 9 with x and y of 43 A each. The second entry is of the closed form and is read as a key whose point is not asked, so the key set supplies every member and the declaration at 4, valid under the first and the first the log published, disputes the post; a reader that finds the entry unusable reports could not be checked.",
            log, post, [0, 1, 4], "disputed", "disputed")
        {
            DeclarationKeys =
            [
                new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, declarationKeyIndex),
                new ExtraLogKey(Renamed(ConformanceLogKeys.Declaration, "extra-decl"), LogKeyValidFrom, LogIndex: 9, OffCurve: true),
            ],
        };
    }

    /// <summary>A log key off the curve under another kid (Amendment 6 ruling 58): <c>keys</c> lists, beside the head key, a copy of the declaration key under <c>another-ec-key</c>, off the curve, at 5.</summary>
    private static Case LogKeyOffCurve(string root, Key k1)
    {
        var (log, post, declarationKeyIndex, decl) = PostThenDeclaration(k1, "81");
        AddDeclaration(log, decl, root, "compromise-log-key-off-curve");
        return new Case("compromise-log-key-off-curve", "R6.62",
            "The keys member lists, beside the head key, an entry under the kid another-ec-key with x and y of 43 A each at 5, and declaration_keys lists the declaration key at 3. The entry is of the closed form and is not the declaring key's, so the declaration at 4 disputes the post; a reader that refuses the document or reads the entry as unreadable reports an error or could not be checked.",
            log, post, [0, 1, 4], "disputed", "disputed")
        {
            ExtraLogKeys = [new ExtraLogKey(Renamed(ConformanceLogKeys.Declaration, "another-ec-key"), LogKeyValidFrom, LogIndex: 5, OffCurve: true)],
            DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, declarationKeyIndex)],
        };
    }

    /// <summary>A log key off the curve under the declaration key's own kid (Amendment 6 ruling 58): <c>keys</c> lists the declaration key's kid with x and y of 43 A at 2, below the declaration at 5 (Amendment 7 ruling 82).</summary>
    private static Case LogKeyOffCurveUnderDeclarationKid(string root, Key k1)
    {
        var (log, post, logKeyIndex, declarationKeyIndex, decl) = PostAfterALogKey(k1, "82");
        var declarationIndex = AddDeclaration(log, decl, root, "compromise-log-key-off-curve-under-declaration-kid");
        return new Case("compromise-log-key-off-curve-under-declaration-kid", "R6.62",
            "The keys member lists, beside the head key, an entry under the declaration key's own kid with x and y of 43 A each at 2, and declaration_keys lists the declaration key at 4. The log key is published below the declaration at 5 and the declaring key's kid is a log key's by kid, so the declaration fails (R6.62(d)); a reader that compares public keys only finds no key in the entry and disputes.",
            log, post, [0, 1, declarationIndex], "failed", "declaration-key-is-log-key")
        {
            ExtraLogKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, LogIndex: logKeyIndex, OffCurve: true)],
            DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, declarationKeyIndex)],
        };
    }

    /// <summary>The declaring key and a log key off the curve at the same points (Amendment 6 ruling 59): both entries state x and y of 43 A, so the declaring key is a log key by the key as stated; the log key is at 2, below the declaration at 5 (Amendment 7 ruling 82).</summary>
    private static Case DeclarationKeyAndLogKeyOffCurve(string root, Key k1)
    {
        var (log, post, logKeyIndex, declarationKeyIndex, decl) = PostAfterALogKey(k1, "83");
        var declarationIndex = AddDeclaration(log, decl, root, "compromise-declaration-key-and-log-key-off-curve");
        return new Case("compromise-declaration-key-and-log-key-off-curve", "R6.62",
            "The declaration key is listed at 4 with x and y of 43 A each, and the keys member lists, beside the head key, an entry under another kid with the same x and y at 2, below the declaration at 5. A log key by public key is the key as the entry states it (kty, crv, x and y, as written), whether or not the point lies on its curve, and R6.62's order asks it before the signature, so the declaration fails as a log key; a reader that reads an entry with no usable point as no key skips the step and fails at the signature.",
            log, post, [0, 1, declarationIndex], "failed", "declaration-key-is-log-key")
        {
            ExtraLogKeys = [new ExtraLogKey(Renamed(ConformanceLogKeys.Declaration, "another-ec-key"), LogKeyValidFrom, LogIndex: logKeyIndex, OffCurve: true)],
            DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, declarationKeyIndex, OffCurve: true)],
        };
    }

    /// <summary>A genuine declaration, and then the declaration key published as a <c>log.key</c> after it (Amendment 7 ruling 82): the key is a log key at 5 and the declaration is at 4, so the declaration stands and disputes the post.</summary>
    private static Case LogKeyPublishedAfterIt(string root, Key k1)
    {
        var (log, post, declarationKeyIndex, decl) = PostThenDeclaration(k1, "85");
        var declarationIndex = AddDeclaration(log, decl, root, "compromise-log-key-published-after-it");
        var logKeyIndex = PublishLogKey(log, ConformanceLogKeys.Declaration);
        return new Case("compromise-log-key-published-after-it", "R6.62",
            "The declaration key is published at 3 as a declaration key and signs the declaration at 4; the keys member lists the same key as a log key at 5. R6.62's log-key check reads the log keys published below the declaration's own index, and this one is published after it, so the declaration stands and disputes the post: a log.key entry appended after a genuine declaration does not undo it.",
            log, post, [0, 1, declarationIndex], "disputed", "disputed")
        {
            ExtraLogKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, LogIndex: logKeyIndex)],
            DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, declarationKeyIndex)],
        };
    }

    /// <summary>The declaring key's own entry in <c>keys</c> gives no <c>log_index</c> (Amendment 7 ruling 82): a log key that gives no position cannot be shown to come after the declaration, so it counts as below.</summary>
    private static Case LogKeyPositionNotGiven(string root, Key k1)
    {
        var (log, post, declarationKeyIndex, decl) = PostThenDeclaration(k1, "86");
        var declarationIndex = AddDeclaration(log, decl, root, "compromise-log-key-position-not-given");
        return new Case("compromise-log-key-position-not-given", "R6.62",
            "The declaration key is published at 3 as a declaration key and signs the declaration at 4; the keys member lists the same key as a log key and gives it no log_index. A log key that gives no position cannot be shown to come after the declaration, so it counts as below it (fail closed) and the declaration fails as a log key.",
            log, post, [0, 1, declarationIndex], "failed", "declaration-key-is-log-key")
        {
            ExtraLogKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, LogIndex: null)],
            DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, declarationKeyIndex)],
        };
    }

    /// <summary>One kid listed twice at one position with the same key stated again under other members (Amendment 6 ruling 59): <c>use</c> <c>enc</c> and another <c>valid_from</c>.</summary>
    private static Case DeclarationKidTwiceAtOnePositionSameKey(string root, Key k1)
    {
        var (log, post, declarationKeyIndex, decl) = PostThenDeclaration(k1, "84");
        AddDeclaration(log, decl, root, "compromise-declaration-kid-twice-at-one-position-same-key");
        return new Case("compromise-declaration-kid-twice-at-one-position-same-key", "R6.62",
            "The declaration key's kid is listed at 3 and again at 3 with the same kty, crv, x and y and use enc and another valid_from. Two listings that state one key are one key whatever else they say (R6.62(c)), so the earliest is at 3, the declaration at 4 is valid under it and disputes the post; a reader that compares every member reads two keys and no position, and reports could not be checked.",
            log, post, [0, 1, 4], "disputed", "disputed")
        {
            DeclarationKeys =
            [
                new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, declarationKeyIndex),
                new ExtraLogKey(ConformanceLogKeys.Declaration, "2026-09-02T00:00:00Z", declarationKeyIndex, UseEnc: true),
            ],
        };
    }

    /// <summary>The same key under another kid: its public key, private key and thumbprint-independent members unchanged, its <c>kid</c> and the JWK's replaced.</summary>
    private static P256LogKey Renamed(P256LogKey key, string kid) =>
        key with { Kid = kid, Jwk = JsonBuilders.WithField((JsonValue.Object)key.Jwk, "kid", Str(kid)) };

    private static Case FromIndexBeforeBinding(string root, Key k1)
    {
        var (log, post, logKeyIndex, decl) = PostThenDeclaration(k1, "49", d => d with { FromIndex = 0 });
        AddDeclaration(log, decl, root, "compromise-from-index-before-binding");
        return new Case("compromise-from-index-before-binding", "R6.57",
            "from_index is 0 and the first kid's binding is at 1: one below the log index of kids[0]'s binding (KF3).",
            log, post, [0, 1, 4], "failed", "declaration-mismatch")
        { DeclarationKeys = [new ExtraLogKey(ConformanceLogKeys.Declaration, LogKeyValidFrom, logKeyIndex)] };
    }

    // ---- entries -------------------------------------------------------------------------------

    /// <summary>A <c>log.key</c> entry, as the operator's tool publishes a log key (R6.50): <c>{ kid, jwk, valid_from }</c>.</summary>
    private static int PublishLogKey(Log log, P256LogKey key) => log.Add("log.key", "log:keys", OperatorRole, Obj(
        ("jwk", key.Jwk), ("kid", Str(key.Kid)), ("valid_from", Str(LogKeyValidFrom))));

    /// <summary>A <c>log.declaration-key</c> entry, as the operator's publish-declaration-key appends it (errata G67, R6.62): <c>{ kid, jwk, valid_from }</c>.</summary>
    private static int PublishDeclarationKey(Log log, P256LogKey key) => log.Add("log.declaration-key", "log:declaration-keys", OperatorRole, Obj(
        ("jwk", key.Jwk), ("kid", Str(key.Kid)), ("valid_from", Str(LogKeyValidFrom))));

    internal static CanonicalBytes DeclarationStatement(string agent, string[] kids, long fromIndex, long prev, string reason, string typ) =>
        Canon(Obj(
            ("agent_id", Str(agent)),
            ("from_index", Num(fromIndex)),
            ("kids", new JsonValue.Array([.. kids.Select(k => Str(k))])),
            ("prev", Num(prev)),
            ("reason", Str(reason)),
            ("typ", Str(typ))));

    private static int AddDeclaration(Log log, Decl d, string root, string caseName)
    {
        var canonical = DeclarationStatement(Agent, d.Kids, d.FromIndex, d.Prev, d.Reason, d.StatementTyp);
        var text = Encoding.UTF8.GetString(canonical.Span);
        var declaration = PinnedOrSigned(
            Path.Combine(root, caseName), Path.Combine("entries"), canonical, text, d.Signer, d.HeaderTyp);
        return log.Add("agent.key-compromised", Agent, OperatorRole, Obj(
            ("agent_id", Str(Agent)),
            ("declaration", Str(declaration)),
            ("from_index", Num(d.FromIndex)),
            ("kids", new JsonValue.Array([.. d.Kids.Select(k => Str(k))])),
            ("prev", Num(d.Prev)),
            ("reason", Str(d.Reason)),
            ("statement", Str(text))));
    }

    /// <summary>
    /// The declaration already pinned in <paramref name="existingDir"/> for exactly this statement, re-verified under the
    /// signer's key and kept; a fresh signature only when the directory does not exist. A directory that exists and holds no
    /// declaration for the statement is refused: ES256 signing is randomized, so re-signing would move bytes a vector pins.
    /// </summary>
    internal static string PinnedOrSigned(
        string existingDir, string entriesSubdirectory, CanonicalBytes canonical, string statementText, P256LogKey signer, string headerTyp)
    {
        var pinned = FindPinned(existingDir, entriesSubdirectory, statementText);
        if (pinned is not null)
        {
            if (!Signing.Verify(canonical, new JwsSignature(pinned), "ES256", signer.Kid, signer.Spki, headerTyp).IsOk)
                throw new InvalidOperationException($"{existingDir}: the pinned declaration does not verify under its log key and typ; it is kept, never re-signed");
            return pinned;
        }

        if (Directory.Exists(existingDir))
        {
            throw new InvalidOperationException(
                $"{existingDir} exists but pins no declaration for this statement; the generator never re-signs. Delete the case deliberately to regenerate it.");
        }

        return Signing.Sign(canonical, "ES256", signer.Kid, signer.EcPrivateKeyDer, headerTyp).Compact;
    }

    private static string? FindPinned(string dir, string entriesSubdirectory, string statementText)
    {
        var searchDir = Directory.Exists(Path.Combine(dir, entriesSubdirectory)) ? Path.Combine(dir, entriesSubdirectory) : dir;
        if (!Directory.Exists(searchDir))
            return null;

        foreach (var file in Directory.EnumerateFiles(searchDir, "*.json").Order(StringComparer.Ordinal))
        {
            using var document = JsonDocument.Parse(File.ReadAllBytes(file));
            var root = document.RootElement;
            var entry = root.ValueKind == JsonValueKind.Object && root.TryGetProperty("entry", out var inner) ? inner : root;
            if (entry.ValueKind != JsonValueKind.Object
                || !entry.TryGetProperty("event_type", out var type) || type.GetString() != "agent.key-compromised"
                || !entry.TryGetProperty("payload", out var payload) || payload.ValueKind != JsonValueKind.Object
                || !payload.TryGetProperty("statement", out var statement) || statement.GetString() != statementText
                || !payload.TryGetProperty("declaration", out var declaration))
            {
                continue;
            }

            return declaration.GetString();
        }

        return null;
    }

    /// <summary>The key-set members after the head key's, as JSON text starting with a comma per key.</summary>
    private static string ExtraLogKeysJson(IReadOnlyList<ExtraLogKey> keys)
    {
        var builder = new StringBuilder();
        foreach (var extra in keys)
        {
            var members = new List<(string, JsonValue)>
            {
                ("alg", Str("ES256")),
                ("crv", Str("P-256")),
                ("kid", Str(extra.Key.Kid)),
                ("kty", Str("EC")),
                ("use", Str("sig")),
                ("valid_from", Str(extra.ValidFrom)),
                ("x", Str(Jwk.Base64UrlEncode(extra.Key.X32))),
                ("y", Str(Jwk.Base64UrlEncode(extra.Key.Y32))),
            };
            if (extra.OmitAlg)
                members.RemoveAll(m => m.Item1 == "alg");
            if (extra.OmitY)
                members.RemoveAll(m => m.Item1 == "y");
            if (extra.StarX)
            {
                members.RemoveAll(m => m.Item1 == "x");
                members.Add(("x", Str("*" + Jwk.Base64UrlEncode(extra.Key.X32)[1..])));
            }

            if (extra.Rsa)
                members = [("alg", Str("RS256")), ("kid", Str("conformance-rsa")), ("kty", Str("RSA")), ("x", Str(Jwk.Base64UrlEncode(extra.Key.X32)))];
            if (extra.OffCurve)
            {
                members.RemoveAll(m => m.Item1 is "x" or "y");
                members.Add(("x", Str(new string('A', 43))));
                members.Add(("y", Str(new string('A', 43))));
            }

            if (extra.UseEnc)
            {
                members.RemoveAll(m => m.Item1 == "use");
                members.Add(("use", Str("enc")));
            }

            if (extra.OmitKid)
                members.RemoveAll(m => m.Item1 == "kid");
            if (extra.LogIndex is { } index)
                members.Add(("log_index", Num(index)));
            builder.Append(',').Append(Encoding.UTF8.GetString(Canon(Obj([.. members])).Span));
        }

        return builder.ToString();
    }

    /// <summary>The key set's <c>declaration_keys</c> member as JSON text, starting with a comma; empty where the case serves no member at all (R6.62(a)).</summary>
    private static string DeclarationKeysJson(Case c) =>
        (c.DeclarationKeysRawJson, c.DeclarationKeys) switch
        {
            ({ } raw, _) => ",\"declaration_keys\":" + raw,
            (null, null) => string.Empty,
            (null, { } keys) => ",\"declaration_keys\":[" + ExtraLogKeysJson(keys).TrimStart(',') + "]",
        };
}
